import React, { useState } from 'react';

import icons from '../site/icons';

const TipCalculator = () => {

  const [amount, setAmount] = useState('');
  const [tipPercent, setTipPercent] = useState(15);
  const [split, setSplit] = useState(1);
  const [focused, setFocused] = useState('amount');

  const amountNum = parseFloat(amount) || 0;
  const tip = amountNum * (tipPercent / 100);
  const total = amountNum + tip;
  const perPerson = split > 1 ? total / split : total;

  return (
    <div 
        className='containerDetail color-yellow size20 m-5 contentLeft' 
        role='region' 
        aria-label='Tip Calculator' 
        style={{maxWidth: 340, margin: '2rem auto', borderRadius: 16, boxShadow: '0 2px 12px #0002'}}
    >
      <div 
        className='containerDetail size20 p-20 color-yellow bg-lite contentLeft' 
        style={{display: 'flex', gap: 12}}
    >
        <span 
            className='size40' 
            aria-hidden='true' 
        >
            {icons.tipcalculator}
        </span>
        Tip Calculator
      </div>
      <form 
        onSubmit={e => e.preventDefault()} 
        className='tip-form pt-20 pl-20' 
        style={{display: 'flex', 
        flexDirection: 'column', 
        gap: 16}}
    >
        <div className='form-group'>
          <label 
            htmlFor='amount' 
            className='mb-5'
          >
            Bill Amount
          </label>
          <input
            id='amount'
            type='number'
            min='0'
            step='0.01'
            value={amount}
            onChange={e => setAmount(e.target.value)}
            aria-label='Bill Amount'
            className='containerBox inputBox color-lite size20 p-10 mt-10'
            autoFocus={focused === 'amount'}
            onFocus={() => setFocused('amount')}
          />
        </div>
        <label htmlFor='tipPercent' className=''>
            Tip %
        </label>
        <div>
            <input
                id='tipPercent'
                type='number'
                min='0'
                max='100'
                value={tipPercent}
                onChange={e => setTipPercent(Number(e.target.value))}
                aria-label='Tip Percentage'
                className='containerBox inputBox color-lite size20 p-10 mt-10'
                onFocus={() => setFocused('tipPercent')}
            />
        </div>
        <div className='form-group'>
          <label 
            htmlFor='split' 
            className='mb-5'
          >
            Split
          </label>
          <div>
            <input
                id='split'
                type='number'
                min='1'
                max='20'
                value={split}
                onChange={e => setSplit(Number(e.target.value))}
                aria-label='Number of People'
                className='containerBox inputBox color-lite size20 p-10 mt-10'
                onFocus={() => setFocused('split')}
            />
          </div>
        </div>
      </form>
      <div 
        className='containerDetail flexContainer p-10 color-yellow tip-results mt-5' 
        aria-live='polite' 
      >
        <div className='flexContainer width-100-percent'>
            <div className='flex2Column contentRight p-10'>
                <div className='mb-10'>
                    Tip:
                </div>
                <div>
                    Total:
                </div>
            </div>
            <div className='flex2Column p-10'>
                <div className='pl-10 color-lite flex2Column mb-10'>
                    ${tip.toFixed(2)}
                </div>
                <div className='pl-10 color-lite flex2Column'>
                    ${total.toFixed(2)}
                </div>
            </div>
        </div>
        
      </div>
      <div className='containerDetail contentCenter pl-40 mt-5'>
            {
                split > 1 && <div>Person/<span className='color-lite'>${perPerson.toFixed(2)}</span>
                            </div>
            }
        </div>
    </div>
  );
};

export default TipCalculator;
